// Create a new functional component called TrendingSong.js that returns an <h2> element with the text 'Trending on Spotify: Calm Down'. 
// Import and use this component inside App.js so it shows below your main heading.



import React from 'react'

function Trendingsong() {
  return (
    <div>

     <h2>Trending on Spotify: Calm Down</h2>
    </div>
  );
}


export default Trendingsong;
